<?php ob_start(); ?><h1>Quarantine</h1><table><tr><th>ID</th><th>Original path</th><th>Quarantine path</th><th>SHA256</th><th>Date</th><th>Status</th><th>Restore</th></tr><?php foreach($items as $i): ?><tr><td><?= e($i['id']) ?></td><td><code><?= e($i['original_path']) ?></code></td><td><code><?= e($i['quarantine_path']) ?></code></td><td><?= e($i['sha256']) ?></td><td><?= e($i['created_at']) ?></td><td><?= e($i['status']) ?></td><td><?php if(config('guard.web_actions_enabled') && $i['status']==='quarantined'): ?><form method="post" action="/quarantine/restore" onsubmit="return confirm('Restore quarantined file?')"><input type="hidden" name="id" value="<?= e($i['id']) ?>"><button class="btn">Restore</button></form><?php else: ?><code>php artisan guard:restore <?= e($i['id']) ?></code><?php endif ?></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
